from build_evidence import *
extra=[
('Which rules take precedence among cards, Law, Learning to Play and faction rules, and can an ordinary card override a cannot?', 'Card beats Law; Law beats Learning to Play. Follow both general and faction when possible, otherwise faction wins. Cannot is absolute unless explicitly overridden.','1.1.1-2','Conflict hierarchy and absolute prohibition are distinct interpretation rules.'),
('Who chooses unclear simultaneous resolutions, and may you interrupt a March between its two moves to take another action or spend a bird?', 'Current turn player chooses unclear simultaneous order/decision maker. Cannot interrupt action including compound March unless effect explicitly permits interruption; no other action or bird expenditure between its moves.','1.1.3;1.4.2','Atomic compound actions and default simultaneous priority.'),
('What do at-start and at-end phase timings mean, and can you take ordinary Daylight actions after beginning the last step of your turn?', 'Start happens before all other phase effects; end after other phase effects but before next phase. Once last turn step begins no actions except explicitly end-of-Evening or end-of-turn actions.','1.4.1;1.4.3','Phase-boundary and terminal-step lockout.'),
('What hand/deck/pile information can players inspect or reveal, and may non-binding deals transfer cards or require consent?', 'Hand counts public, contents cannot be shown/revealed unless instructed. Face-up piles inspectable/searchable, shared deck not. Agreements non-binding, card giving only when instructed, actions never require consent.','1.2-3','Information rights and negotiation constraints.'),
('What happens immediately when shared deck empties, and how do bird substitutions work for forced non-bird discards versus explicit bird costs?', 'Immediately shuffle discard into new deck. Bird can match non-bird including multiple matching-card costs; forced non-bird give/discard must include birds. Non-bird cannot substitute for explicit bird.','2.1;2.1.1','Deck reshuffle timing and mandatory versus one-way suit substitution.'),
('If instructed to place more pieces than remain, can you use proxies or choose to place fewer than available, and does shortage waive costs or Eyrie obligations?', 'No proxies; pieces finite. Must place maximum possible, not choose fewer. Costs/prerequisites not waived; required Decree action still must fully complete or turmoil.','1.5.1;1.5.4;7.5.2','Supply exhaustion versus obligatory full completion.'),
('Where do placed and removed pieces normally come from/go, what happens to removed items, and when do effects of simultaneous removals trigger?', 'Place from supply or leftmost prompted tracked piece. Remove to supply or rightmost empty track space; otherwise permanently, items permanently. Remove all simultaneous pieces before triggering removal effects.','1.5.4;G.20;G.24','Default component destinations and simultaneous-removal sequencing.'),
('When a player is forced to move or battle, whose restrictions/abilities and battle decisions apply?', 'Resolve as if affected player chose it, with their abilities/restrictions; forced battling player makes all battle decisions.','1.5.5','Forced actions preserve actor rules and decision rights.'),
('Can an enemy replace a piece in the Keep clearing, and how is a swap different from a move or place?', 'Replacement requires ability both to remove old and place new; enemy cannot place at keep so replacement fails. Swap ignores move/place restrictions including keep.','G.23;G.33;6.2.2','Replace prerequisites and swap exception.'),
('When two players simultaneously reach 30 VP, who wins?', 'Tied player closest clockwise to current player wins, including current player.','3.1.1','Simultaneous victory priority.'),
('How do forest adjacency and Winter river affect Vagabond Slip, and does Fall add any special map rule?', 'Forest adjacent to touching clearings without crossing printed path and forests separated by one printed path. Winter river divides forests as paths do; Fall has no special rule. Slip uses this adjacency. Rivers otherwise are not paths.','2.3-4;M.1-2;9.4.2','Forest adjacency and Winter topology exception.'),
('Give Marquise standard starting placements and supplies, including its unoccupied corner and building-track arrangement.', '25 warriors,8 wood supply; keep any corner. One warrior each clearing except diagonally opposite corner. One sawmill/workshop/recruiter among keep and adjacent clearings respecting slots. Other five of each type on tracks right to left, leftmost empty.','6.3','Complete Marquise setup procedure.'),
('Give Eyrie standard starting placements, leader/Vizier procedure and remaining roost arrangement.', '20 warrior supply; roost and six warriors in corner not another starting corner, diagonally opposite starting corner if possible. Choose leader, others face up; Viziers in indicated columns. Six remaining roosts track right to left.','7.3','Complete Eyrie setup including updated corner placement.'),
('What does Alliance start with in supply, on its board, in hand/supporters, and on the map?', '10 warriors supply;3 bases on matching board spaces,10 sympathy track. Three hand cards from common setup plus three additional supporters face down. No map pieces/officers.','5.1.3;8.3','Alliance independent initial supporters versus hand.'),
('Describe Vagabond setup other than hidden ruin items: pawn, quests, relationships and marked starting items.', 'Choose character, pawn any forest; shuffle quests and display three; relationships Indifferent for each other faction. Take S-marked listed character items, tea/coins/bags face up on matching tracks, others Satchel; unused S items box.','9.3','Vagabond public quest and character item setup.'),
('What Reach totals and base-faction values guide choosing two-, three- and four-player mixes?', 'Recommended17/18/21 respectively; Marquise10,Eyrie7,Vagabond5,Alliance3. Adventurous any mix17+.','5.2','Faction-mix setup guideline.'),
('When and how much wood does Marquise produce, what limits production, and how does its Evening draw work?', 'Birdsong one wood per sawmill in its clearing, finite eight wood supply. Evening one card plus uncovered draw bonuses, discard to five.','6.4;6.6;1.5.1','Mandatory production and Marquise draw procedure.'),
('If Marquise Recruit has more eligible recruiters than available warriors, what is placed and who chooses where?', 'Once-per-turn Recruit places one per recruiter as far as supply allows; maximum available, Marquise chooses eligible placements when shortage.','6.5.3;1.5.4;1.1.3','Recruit shortage allocation distinct from normal limit.'),
('How do Eyrie item crafting and its Builder leader interact with printed VP and extra crafting-point effects?', 'Normally ignore printed VP and score one; extra crafting-point effects still apply. Builder ignores Disdain so printed VP applies.','7.2.3;7.8.1','Disdain and Builder exception.'),
('For each Eyrie leader give the Vizier columns and special ability.', 'Builder Recruit/Move ignore Disdain; Charismatic Recruit/Battle must recruit two; Commander Move/Battle extra attacker hit; Despot Move/Build one extra VP when removing at least one enemy building/token in battle.','7.8','Leader setup-dependent mandatory/special effects.'),
('If Charismatic must Recruit but only one Eyrie warrior remains in supply, can placing that one fulfill the Decree?', 'No. Charismatic requires two; inability fully complete causes immediate turmoil despite maximum-possible piece placement.','7.8.2;7.5.2;1.5.4','Charismatic shortage forces turmoil rather than partial Decree success.'),
('Does Alliance Guerrilla War bypass warrior limits, and how are the dice assigned when Alliance defends?', 'Alliance defending takes higher die, attacker lower; both rolled-hit warrior caps still apply.','8.2.2;4.3.3.I','Guerrilla reversal retains cap.'),
('Can Alliance craft from Supporters, inspect them, or count them toward its five-card hand limit?', 'Supporters spent only for suit, not crafted or treated as hand cards. Alliance may inspect own face-down stack. They do not count against hand limit.','8.2.3;8.5.1','Supporter information and use restrictions.'),
('Can Alliance first Spread Sympathy into a clearing and then Revolt there in that same Birdsong?', 'No. All Revolts precede Spread Sympathy; cannot return to Revolt step after spreading.','8.4','Phase-step ordering blocks new-sympathy immediate revolt.'),
('Do two enemy players each having two warriors trigger Martial Law when spreading sympathy, and does Martial Law increase Organize cost?', 'No: requires at least three warriors of one other player, not combined enemies. Organize costs removal of own warrior, no supporters and no Martial Law surcharge.','8.4.2.IIa;8.6.1.IV','Martial Law single-player threshold and operation exception.'),
('Does placing warriors in a sympathetic clearing or moving only Vagabond pawn there cause Outrage, and what if allied warriors accompany Vagabond?', 'Placement and pawn-only movement do not trigger warrior-entry Outrage. Moving allied warriors there does trigger it.','8.2.6;9.2.9.IIb;1.5.5','Move-versus-place/pawn trigger distinction and allied-force interaction.'),
('What Alliance Evening operations are available, does using an officer consume it, and when are cards drawn?', 'Up to officer count actions in any order/repetition: Move once, Battle once, Recruit one at base, Organize remove warrior from unsympathetic clearing to place sympathy and score. Officers not consumed. After operations draw one plus uncovered bonuses then discard to five.','8.6','Full military operation menu and nonconsumable action budget.'),
('What happens to Vagabond pawn when a revolt or another enemy remove-all-pieces effect hits its clearing?', 'Pawn remains on map and damages three items; it cannot be removed.','9.2.2.I','Vagabond full-removal replacement effect.'),
('What determines Vagabond rolled hits and defenseless status, do exhausted swords count, and how are excess hits handled?', 'Rolled cap is all undamaged swords in Satchel face up or down. Exhausted undamaged swords count. Defenseless defending if no undamaged swords. Each hit damages one undamaged item; ignore hits after all undamaged items gone.','9.2.4;9.2.6-7','Vagabond sword cap, defensive threshold and excess-hit immunity.'),
('How do tea/coins/bags enter or leave item tracks, what is track capacity, and can damaged face-up items pay actions?', 'Face-up tea/coins/bags in Satchel move to empty matching track space when able; each track capacity three. Exhaust track item into Satchel. Damaged items cannot pay actions even if face up; exhaustion requires face-up undamaged item.','9.2.5','Track routing/cap and independent damage/readiness states.'),
('How is Vagabond capacity calculated, what counts toward load, when is it checked and where do excess items go?', 'Last step Evening: Satchel plus Damaged load, limit six plus two per face-up bag on track. Track items excluded. Permanently remove chosen Satchel/Damaged items until limit; not immediate on acquisition.','9.6.4;9.2.5','Capacity timing, load and permanent disposal.'),
('Does forest Rest refresh an undamaged exhausted item, and how does it differ from Refresh or Repair?', 'Rest returns all damaged items to Satchel face up, but does not refresh undamaged exhausted items. Refresh flips exhausted face up without repairing damage. Repair moves one damaged item to Satchel keeping face.','9.4.1;9.5.7;9.6.1','Orthogonal damage/exhaustion state transitions.'),
('What is Vagabond Aid cost and target, is a crafted item required, and how are repeated Aid relationship improvements counted?', 'Exhaust any ready undamaged item, give matching clearing card to player with faction pieces there. May take crafted item if present, but Aid can occur without item. For non-hostile faction meet printed Aid count within same turn per step, each Aid counts once toward one improvement; advance and score new space.','9.5.4;9.2.9.I','Aid targeting/payment, optional reward and per-turn progression.'),
('What changes at Allied status: Aid points, moving warriors and attacking with them, and can you use allied warriors against their own faction?', 'Each Aid to Allied scores two. May force one Allied faction warriors to accompany move to destination clearing subject to movement rules. At start as attacker may treat one ally warriors there as own, cap warriors plus undamaged swords; cannot use against that same faction.','9.2.9.II;1.5.5','Allied status powers and self-attack exception.'),
('When Vagabond takes hits using allied warriors, when and under what comparison does that ally become Hostile?', 'If more hits are taken removing allied warriors than damaging items in same battle, ally becomes Hostile at battle end. Equal counts do not. Overrides ordinary first-warrior hostility trigger for these battle losses.','9.2.9.IId','Deferred allied-casualty hostility with strict inequality.'),
('Can Vagabond craft a card requiring fox and rabbit icons from one clearing, reuse the pawn for multiple craftings, and immediately use a crafted item?', 'Cannot satisfy mixed suits because clearing must match every icon. Each icon exhausts hammer, pawn may activate repeatedly ignoring once/turn cap. Crafted item can immediately be taken face up, usable if otherwise eligible.','9.2.1;9.5.8','Vagabond multi-icon crafting restriction and repeated pawn exception.'),
('List base Vagabond characters with starting items and special action costs/results, including Ranger timing.', 'Thief boot/torch/tea/sword, exhaust torch Steal random hand card from player with faction pieces in clearing. Tinker boot/torch/bag/hammer, exhaust torch Day Labor matching discard card, bird always valid. Ranger boot/torch/crossbow/sword, exhaust torch Hideout repair three retaining faces, immediately end Daylight for Evening.','V.1-3;9.5.7','Base-character distinct powers and forced phase end.'),
('After removing a ruin last item, what happens to its building slot, and can ordinary building placement remove a ruin instead?', 'Remove ruin and slot becomes open. Ordinary placement cannot remove ruin; ruins removable only explicitly, and building needs open slot.','2.2.3-4;9.5.3','Ruin slot transition and blocked placement.'),
('Can a coalition partner be attacked as an enemy, and does coalition automatically grant Allied relationship powers?', 'Coalition partners are not enemies so cannot choose partner as battle enemy. Coalition itself does not grant Allied; relationships still separate and hostile partner resets Indifferent.','G.8;4.3;9.2.8-9','Coalition enemy-status exclusion distinct from Allied status.'),
('A Vagabond battles a previously non-Hostile faction on its own turn, removes two warriors followed by one building. How much removal/Infamy VP, and why?', 'First warrior makes faction Hostile but gives no Infamy. Second warrior gives one Infamy; building gives one normal plus one Infamy. Three VP total.','9.2.9.IIIa;3.2.1','Hostility transition within one battle excludes only triggering warrior.'),
('What is the cost of a normal Vagabond move into a clearing with only hostile buildings versus one with hostile warriors from several factions?', 'Only buildings: one boot. Any hostile warriors: one base plus one extra boot, not one extra per faction. Slip remains free even into hostile warriors.','9.5.1;9.2.9.IIIb;9.4.2','Hostile-warrior condition and nonstacking extra movement cost.'),
('Does taking an available dominance card activate it immediately, and do taking/activating use a Marquise action?', 'Taking puts it into hand only; activation separate during Daylight with at least ten VP. Neither procedure requires spending Marquise/faction action allowance.','3.3.1;3.3.4;6.5','Dominance actions independent of faction action budget.'),
('Can ownership of faction pieces change, and are items faction pieces that belong to the faction holding them?', 'Faction piece ownership cannot change; starting faction owns its listed faction pieces except items. Items are not faction pieces and are not owned by a faction.','1.5.2-3;G.10;G.13','Permanent piece identity versus item possession.'),
('What happens to immediate-effect versus persistent crafting cards, and can a card in your play area be spent as though in hand?', 'Resolve immediate effect then discard card. Persistent effect card stays in play area granting its effect. Cards there are not hand cards and can only be spent/discarded/otherwise used if explicitly instructed.','4.1.2-3;2.1.4;G.21','Crafted-card destinations and restricted play-area reuse.'),
('Can ambush or dominance cards be crafted, and what are their other permitted uses?', 'Neither can be crafted. Ambush can be played for immediate battle hits/foil; dominance can be activated for altered win condition or spent for suit.','2.1.2-3;3.3.3;4.3.1','Noncraftable special card types versus ordinary craftable effects.'),
('In standard setup how are starting player/seating, score markers and dice arranged, and does faction setup order set turn order?', 'Random starting player and seating; score markers zero; dice near map. Faction setup letter order distinct from random turn order.','5.1.1-2;5.1.6-7','Random turn order versus deterministic faction setup order.')]
if __name__=='__main__':
 B=R/'benchmark-v2';B.mkdir()
 oldq=json.loads((R/'benchmark-v1/questions.json').read_text());oldk=json.loads((R/'benchmark-v1/answer-key.json').read_text())
 oldq['benchmark_version']='v2';oldk['benchmark_version']='v2'
 for i,(q,a,s,n) in enumerate(extra,21):
  oldq['questions'].append({'id':f'Q{i:02}','question':q});oldk['answers'].append({'id':f'Q{i:02}','expected_answer':a,'source_references':s})
 save(B/'questions.json',oldq);save(B/'answer-key.json',oldk)
 save(R/'coverage-ledger.json',{'scope':scope,'criterion':'New rule, rule-defined distinct outcome branch, or consequential timing/priority/exception interaction. Reject cosmetic variants/numbers/mechanical recombinations.','passes':[{'pass':1,'focus':'Golden rules, information, timing, setup, shared limits, Marquise/Eyrie/Alliance distinct branches','accepted':[f'Q{i:02}' for i in range(21,48)],'count':27},{'pass':2,'focus':'Vagabond item lifecycle, allies, character powers, coalition status and cross-system timing','accepted':[f'Q{i:02}' for i in range(48,21+len(extra))],'count':len(extra)-27}], 'accepted':[{'id':f'Q{i:02}','source_references':s,'novelty':n} for i,(q,a,s,n) in enumerate(extra,21)],'rejected':[],'coverage_map':[]})
 text='# Root readable question/answer bank v2\n\n'+scope+'\n\n'
 for q,a in zip(oldq['questions'],oldk['answers']):text+=f"## {q['id']}\n\n{q['question']}\n\n**Expected:** {a['expected_answer']}\n\n**Law:** {a['source_references']}\n\n"
 (B/'question-bank.md').write_text(text)
